<?php require 'includes/functions.php';require_login();$st=$pdo->prepare('SELECT * FROM reports WHERE user_id=? ORDER BY created_at DESC');$st->execute([user()['id']]);$rs=$st->fetchAll();$title='Mi perfil';require 'includes/header.php';?><main class="dashboard"><div class="panel"><div class="author"><span class="avatar" style="width:60px;height:60px;font-size:24px"><?=e(mb_substr(user()['name'],0,1))?></span><div><h2 style="margin:0"><?=e(user()['name'])?></h2><span class="muted"><?=e(user()['email'])?> · <?=e(user()['role'])?></span></div></div></div><h2>Mis reportes</h2><div class="feed"><?php foreach($rs as $r):?><a class="post" href="<?=url('reports/view.php?id='.$r['id'])?>"><div class="post-body"><span class="badge <?=e($r['type'])?>"><?=$r['type']==='lost'?'PERDIDO':'ENCONTRADO'?></span><h3><?=e($r['title'])?></h3><p>📍 <?=e($r['location'])?></p><span class="muted small"><?=$r['status']==='resolved'?'Caso resuelto':($r['status']==='open'?'Activo':'Oculto')?></span></div></a><?php endforeach;?></div></main><?php require 'includes/footer.php';?>